/* =========================================================
   NUSANTARA CARGO — FOOTER V2
   Desktop: 4 kolom sejajar, mengikuti desain sampel.
   Mobile: kolom turun secara responsif tanpa overflow horizontal.
   \========================================================= */
.site-footer{
    position:relative;
    isolation:isolate;
    overflow:hidden;
    width:100%;
    margin:0;
    padding:42px 0 0;
    color:#fff;
    background:#061b3f;
}

.site-footer::before{
    content:"";
    position:absolute;
    inset:0;
    z-index:-2;
    background-image:url('/uploads/media/footer-background.png?v=1789967850');
    background-position:center center;
    background-size:cover;
    background-repeat:no-repeat;
}

/* Overlay dibuat cukup gelap supaya teks putih tetap terbaca,
   tetapi gambar kapal/truk/pesawat masih terlihat seperti sampel. */
.site-footer::after{
    content:"";
    position:absolute;
    inset:0;
    z-index:-1;
    background:linear-gradient(
        90deg,
        rgba(2,18,48,.88) 0%,
        rgba(3,24,55,.82) 48%,
        rgba(2,17,42,.70) 100%
    );
    pointer-events:none;
}

.site-footer .footer-inner{
    width:min(1390px,92%);
    margin:0 auto;
}

/* KUNCI PERBAIKAN: 4 kolom tetap pada desktop.
   Sebelumnya hanya ada 3 kolom sehingga kolom Hubungi Kami
   jatuh ke baris kedua. */
.site-footer .footer-grid{
    display:grid;
    grid-template-columns:1.20fr 1fr 1fr 1.22fr;
    align-items:start;
    min-width:0;
}

.site-footer .footer-brand,
.site-footer .footer-column{
    min-width:0;
}

.site-footer .footer-brand{
    padding:4px 42px 0 0;
}

.site-footer .footer-column{
    min-height:245px;
    padding:4px 34px 0;
    border-left:1px solid rgba(255,255,255,.28);
}

.site-footer .footer-column:last-child{
    padding-right:0;
}

.site-footer .footer-logo{
    display:block;
    width:290px;
    max-width:100%;
    height:auto;
    max-height:112px;
    object-fit:contain;
    object-position:left center;
    margin:0;
}

.site-footer .footer-heading{
    margin:0 0 17px;
    color:#fff;
    font-size:21px;
    line-height:1.2;
    font-weight:800;
    text-transform:uppercase;
    letter-spacing:.15px;
}

.site-footer .footer-heading::after{
    content:"";
    display:block;
    width:38px;
    height:3px;
    margin-top:10px;
    background:#e90013;
    border-radius:3px;
}

.site-footer .footer-links{
    display:flex;
    flex-direction:column;
    gap:10px;
}

.site-footer .footer-links a,
.site-footer .footer-contact p{
    margin:0;
    color:rgba(255,255,255,.94);
    font-size:15px;
    line-height:1.45;
    text-decoration:none;
}

.site-footer .footer-links a{
    display:flex;
    align-items:center;
    min-width:0;
    transition:color .2s ease,transform .2s ease;
}

.site-footer .footer-links a:hover{
    color:#fff;
    transform:translateX(3px);
}

.site-footer .footer-links a span,
.site-footer .footer-contact .contact-icon{
    flex:0 0 27px;
    width:27px;
    color:#ed0015;
    font-weight:800;
}

.site-footer .footer-links a span{
    font-size:17px;
}

.site-footer .footer-contact{
    display:flex;
    flex-direction:column;
    gap:12px;
}

.site-footer .footer-contact p{
    display:flex;
    align-items:flex-start;
}

.site-footer .footer-contact .contact-icon{
    font-size:17px;
    line-height:1.35;
}

.site-footer .footer-contact p > span:last-child{
    overflow-wrap:anywhere;
}

.site-footer .footer-bottom{
    margin-top:24px;
    min-height:58px;
    border-top:1px solid rgba(255,255,255,.28);
    display:flex;
    align-items:center;
    justify-content:flex-start;
    color:rgba(255,255,255,.88);
    font-size:13px;
}

.site-footer .footer-bottom strong{
    color:#fff;
}

@media (max-width:1100px){
    .site-footer .footer-inner{width:min(94%,1390px)}
    .site-footer .footer-grid{
        grid-template-columns:1.1fr 1fr 1fr 1.15fr;
    }
    .site-footer .footer-brand{padding-right:26px}
    .site-footer .footer-column{padding-left:24px;padding-right:20px}
    .site-footer .footer-logo{width:250px}
    .site-footer .footer-heading{font-size:19px}
    .site-footer .footer-links a,
    .site-footer .footer-contact p{font-size:14px}
}

@media (max-width:820px){
    .site-footer{padding-top:34px}
    .site-footer .footer-grid{
        grid-template-columns:1fr 1fr;
        row-gap:28px;
    }
    .site-footer .footer-brand{
        grid-column:1 / -1;
        padding:0 0 6px;
    }
    .site-footer .footer-column{
        min-height:0;
    }
    .site-footer .footer-logo{width:245px}
}

@media (max-width:560px){
    .site-footer{padding:30px 0 0}
    .site-footer .footer-inner{width:calc(100% - 32px)}
    .site-footer .footer-grid{
        grid-template-columns:1fr;
        row-gap:0;
    }
    .site-footer .footer-brand{
        grid-column:auto;
        padding:0 0 25px;
    }
    .site-footer .footer-column{
        padding:22px 0 0;
        min-height:0;
        border-left:0;
        border-top:1px solid rgba(255,255,255,.18);
    }
    .site-footer .footer-column:last-child{
        padding-right:0;
    }
    .site-footer .footer-logo{
        width:225px;
        max-height:92px;
    }
    .site-footer .footer-heading{
        font-size:18px;
        margin-bottom:14px;
    }
    .site-footer .footer-links{gap:8px}
    .site-footer .footer-links a,
    .site-footer .footer-contact p{font-size:14px}
    .site-footer .footer-bottom{
        margin-top:24px;
        min-height:0;
        padding:15px 0 18px;
        line-height:1.5;
    }
}

