(function(){
    var api='/chat_api.php';
    var panel=document.getElementById('nc-chat-panel');
    var launcher=document.getElementById('nc-chat-launcher');
    var close=document.getElementById('nc-chat-close');
    var box=document.getElementById('nc-chat-messages');
    var form=document.getElementById('nc-chat-form');
    var nameInput=document.getElementById('nc-chat-name');
    var phoneInput=document.getElementById('nc-chat-phone');
    var msgInput=document.getElementById('nc-chat-message');
    var timer=null;

    function loadChat(){
        fetch(api+'?action=customer_messages',{cache:'no-store'})
        .then(function(r){return r.json();})
        .then(function(d){
            if(!d.ok)return;
            if(d.conversation){
                nameInput.value=d.conversation.customer_name||nameInput.value;
                phoneInput.value=d.conversation.customer_phone||phoneInput.value;
            }

            box.innerHTML='';
            if(!d.messages || !d.messages.length){
                box.innerHTML='<div style="text-align:center;color:#7d899a;font-size:12px;padding:28px 15px">Halo 👋<br>Silakan kirim pesan kepada Customer Service kami.</div>';
                return;
            }

            d.messages.forEach(function(m){
                var b=document.createElement('div');
                b.className='nc-chat-bubble '+m.sender_type;

                var text=document.createElement('div');
                text.textContent=m.message;
                b.appendChild(text);

                var sm=document.createElement('small');
                sm.textContent=m.created_at;
                b.appendChild(sm);

                box.appendChild(b);
            });
            box.scrollTop=box.scrollHeight;
        })
        .catch(function(){});
    }

    launcher.onclick=function(){
        panel.classList.add('open');
        loadChat();
        if(!timer)timer=setInterval(loadChat,3000);
    };

    close.onclick=function(){
        panel.classList.remove('open');
    };

    form.onsubmit=function(e){
        e.preventDefault();

        var name=nameInput.value.trim();
        var phone=phoneInput.value.trim();
        var message=msgInput.value.trim();

        if(!name || !message)return;

        var fd=new FormData();
        fd.append('action','customer_send');
        fd.append('name',name);
        fd.append('phone',phone);
        fd.append('message',message);

        var btn=form.querySelector('.nc-chat-send');
        btn.disabled=true;

        fetch(api,{method:'POST',body:fd})
        .then(function(r){return r.json();})
        .then(function(d){
            btn.disabled=false;
            if(d.ok){
                msgInput.value='';
                loadChat();
            }else{
                alert(d.error||'Pesan gagal dikirim.');
            }
        })
        .catch(function(){
            btn.disabled=false;
            alert('Koneksi ke Live Chat gagal.');
        });
    };
})();

